INSERT INTO `support_ticket_replies` VALUES (1,1,12,'Uploading our Grade 6 list fails at row 38 with \"Invalid date format\". Worked last month.',NULL,'2026-07-02 03:44:00'),(2,1,1,'Thanks for reporting. Could you attach the CSV? Row 38 likely has a BS date instead of AD.',NULL,'2026-07-02 06:10:00'),(3,1,12,'Attached. You are right — some dates are in BS format. The previous import accepted both.',NULL,'2026-07-02 08:35:00'),(4,2,11,'Please change our WhatsApp sender name from \"SunriseEdu\" to \"Sunrise Public School\".',NULL,'2026-07-01 04:52:00'),(5,2,1,'Request submitted to the WhatsApp Business team. Usually takes 2-3 business days.',NULL,'2026-07-01 10:00:00'),(6,3,15,'We want a flat Rs 100 fine after the 10th of each month. Where do we set this?',NULL,'2026-06-29 06:30:00'),(7,3,1,'Fee Management > Fee Structures > edit the fee type and set late fine amount and due day.',NULL,'2026-06-29 11:15:00'),(8,4,13,'Marksheets generated this week still show our old logo though we updated it two weeks ago.',NULL,'2026-06-27 03:20:00'),(9,5,14,'Is live GPS tracking of buses on the roadmap? Parents keep asking.',NULL,'2026-06-20 07:42:00'),(10,5,1,'It is on the roadmap for Q4 2026 (Premium). Added your school to the early-access list.',NULL,'2026-06-21 03:35:00'),(11,5,14,'Great, thanks — closing this for now.',NULL,'2026-06-21 04:30:00'),(12,6,18,'We purchased 5,000 SMS credits yesterday but the balance still shows 120.',NULL,'2026-06-14 06:00:00'),(13,6,1,'Gateway webhook was delayed. Credits applied manually — balance now shows 5,120. Apologies!',NULL,'2026-06-14 09:25:00');
/*!40000 ALTER TABLE `support_ticket_replies` ENABLE KEYS */;
UNLOCK TABLES;

