--
-- Table structure for table `vehicles`
--

DROP TABLE IF EXISTS `vehicles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vehicles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `vehicle_no` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `vehicle_type` enum('bus','van','other') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'bus',
  `capacity` smallint(5) unsigned DEFAULT NULL,
  `driver_id` bigint(20) unsigned DEFAULT NULL,
  `helper_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `helper_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `insurance_expiry` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_vehicle` (`school_id`,`vehicle_no`),
  KEY `fk_v_driver` (`driver_id`),
  CONSTRAINT `fk_v_driver` FOREIGN KEY (`driver_id`) REFERENCES `staff` (`id`),
  CONSTRAINT `fk_v_school` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
